function MillstoneGrainFeedChuteMaker.init() MillstoneGrainFeedChuteMaker.ironStock=14; MillstoneGrainFeedChuteMaker.bronzeStock=12; MillstoneGrainFeedChuteMaker.woodStock=14; MillstoneGrainFeedChuteMaker.leatherStock=8; MillstoneGrainFeedChuteMaker.silverStock=8; MillstoneGrainFeedChuteMaker.goldStock=6; MillstoneGrainFeedChuteMaker.jewelStock=4; MillstoneGrainFeedChuteMaker.pearlStock=4; MillstoneGrainFeedChuteMaker.productStock={}; MillstoneGrainFeedChuteMaker.buildings={}; MillstoneGrainFeedChuteMaker.maker=nil; MillstoneGrainFeedChuteMaker.activeMaking={}; MillstoneGrainFeedChuteMaker.totalProducts=0; MillstoneGrainFeedChuteMaker.dayTimer=0; print("[MillstoneGrainFeedChuteMaker] Royal Millstone Grain Feed Chute Maker System initialized (6 products, 4 buildings)") end
function MillstoneGrainFeedChuteMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillstoneGrainFeedChuteMaker.maker={name=n or ("Žlebnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žlebnik najet: %s (spretnost: %d)",MillstoneGrainFeedChuteMaker.maker.name,s),"success") end; return true end
function MillstoneGrainFeedChuteMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillstoneGrainFeedChuteMaker.build(id) local ok,e=MillstoneGrainFeedChuteMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillstoneGrainFeedChuteMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
