function MillstoneGrainFeedChuteMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillstoneGrainFeedChuteMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillstoneGrainFeedChuteMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillstoneGrainFeedChuteMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillstoneGrainFeedChuteMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillstoneGrainFeedChuteMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillstoneGrainFeedChuteMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillstoneGrainFeedChuteMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillstoneGrainFeedChuteMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillstoneGrainFeedChuteMaker.buildings==0 then return false,"Potrebna žlebna delavnica" end; if not MillstoneGrainFeedChuteMaker.maker then return false,"Potreben zlebnik" end; return true end
