function MillstoneGrainFeedChuteMaker.completeMaking(m) local q=1.0+(MillstoneGrainFeedChuteMaker.getQualityBonus()/100); if MillstoneGrainFeedChuteMaker.maker then q=q+(MillstoneGrainFeedChuteMaker.maker.skill/140) end; q=math.min(2.5,q); MillstoneGrainFeedChuteMaker.productStock[m.productType]=(MillstoneGrainFeedChuteMaker.productStock[m.productType] or 0)+m.quantity; MillstoneGrainFeedChuteMaker.totalProducts=MillstoneGrainFeedChuteMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillstoneGrainFeedChuteMaker.maker then MillstoneGrainFeedChuteMaker.maker.itemsMade=MillstoneGrainFeedChuteMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillstoneGrainFeedChuteMaker.maker.skill=math.min(100,MillstoneGrainFeedChuteMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Žleb izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millstonegrainfeedchute.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
